INSERT INTO public.test_catalogue (code, owner_id, name, category, normal_price, discount_price, parameters_count, active, is_panel, notes) VALUES ('LEG-008', NULL, 'Anti-Phospholipid Antibody', 'Biochemistry', 900, 810, 1, TRUE, false, '["Higher LDL/non-HDL/triglycerides may increase cardiovascular risk; interpretation depends on age and overall risk.","Very low values need context; low HDL can be a risk marker.","Fasting may be requested for selected situations; follow the ordering clinician/lab instructions.","See the dedicated Lipid Profile Reference Notes sheet. Values are not a diagnosis or a personal treatment target."]'::jsonb) ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, normal_price = EXCLUDED.normal_price, discount_price = EXCLUDED.discount_price, notes = EXCLUDED.notes;
INSERT INTO public.test_catalogue (code, owner_id, name, category, normal_price, discount_price, parameters_count, active, is_panel, notes) VALUES ('LEG-009', NULL, 'Anti-TPO', 'Serology / Immunology', 800, 720, 1, TRUE, false, '["May suggest overactive thyroid or autoimmune activity depending on the test.","May suggest underactive thyroid for hormone tests; antibody results require context.","Usually blood sample; tell the clinician about thyroid medicines and supplements.","Pregnancy and age affect reference intervals; antibody positivity alone is not a complete diagnosis."]'::jsonb) ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, normal_price = EXCLUDED.normal_price, discount_price = EXCLUDED.discount_price, notes = EXCLUDED.notes;
INSERT INTO public.test_catalogue (code, owner_id, name, category, normal_price, discount_price, parameters_count, active, is_panel, notes) VALUES ('LEG-010', NULL, 'Anti-Thyroglobulin Antibody', 'Serology / Immunology', 800, 720, 1, TRUE, false, '["May occur with liver-cell injury, bile-duct problems, alcohol/medicine effects or other conditions.","May reflect reduced protein production or other causes depending on the marker.","Usually blood sample; fasting depends on panel and laboratory.","Enzyme elevation does not by itself establish a specific liver disease."]'::jsonb) ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, normal_price = EXCLUDED.normal_price, discount_price = EXCLUDED.discount_price, notes = EXCLUDED.notes;
