INSERT INTO public.test_catalogue (code, owner_id, name, category, normal_price, discount_price, parameters_count, active, is_panel, notes) VALUES ('LEG-015', NULL, 'Blood Culture', 'Microbiology', 400, 360, 1, TRUE, false, '["A positive/reactive result may indicate current or past infection depending on the assay.","A negative result may not exclude very early infection or infection outside the test''s detection window.","Sample type and timing are test-specific; follow collection instructions.","Confirmatory testing and clinical correlation may be required; screening tests are not always definitive."]'::jsonb) ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, normal_price = EXCLUDED.normal_price, discount_price = EXCLUDED.discount_price, notes = EXCLUDED.notes;
INSERT INTO public.test_catalogue (code, owner_id, name, category, normal_price, discount_price, parameters_count, active, is_panel, notes) VALUES ('LEG-016', NULL, 'Blood Group', 'Haematology', 60, 55, 1, TRUE, false, '["Not interpreted as high/low; reports a blood-group type.","Not interpreted as high/low; reports a blood-group type.","Blood sample; ensure correct patient identification.","Important for transfusion and pregnancy care; crossmatching is separate."]'::jsonb) ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, normal_price = EXCLUDED.normal_price, discount_price = EXCLUDED.discount_price, notes = EXCLUDED.notes;
