INSERT INTO public.test_catalogue (code, owner_id, name, category, normal_price, discount_price, parameters_count, active, is_panel, notes) VALUES ('LEG-041', NULL, 'Estradiol (E2)', 'Biochemistry', 500, 450, 1, TRUE, false, '["May reflect hormone excess, physiological cycle variation, medication effects or endocrine conditions.","May reflect reduced hormone production or timing-related variation.","Collection time and menstrual-cycle timing may matter; disclose medicines and pregnancy status.","Use age-, sex-, cycle- and pregnancy-specific reference intervals."]'::jsonb) ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, normal_price = EXCLUDED.normal_price, discount_price = EXCLUDED.discount_price, notes = EXCLUDED.notes;
INSERT INTO public.test_catalogue (code, owner_id, name, category, normal_price, discount_price, parameters_count, active, is_panel, notes) VALUES ('LEG-042', NULL, 'FSH', 'Biochemistry', 350, 315, 1, TRUE, false, '["May reflect hormone excess, physiological cycle variation, medication effects or endocrine conditions.","May reflect reduced hormone production or timing-related variation.","Collection time and menstrual-cycle timing may matter; disclose medicines and pregnancy status.","Use age-, sex-, cycle- and pregnancy-specific reference intervals."]'::jsonb) ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, normal_price = EXCLUDED.normal_price, discount_price = EXCLUDED.discount_price, notes = EXCLUDED.notes;
INSERT INTO public.test_catalogue (code, owner_id, name, category, normal_price, discount_price, parameters_count, active, is_panel, notes) VALUES ('LEG-043', NULL, 'Ferritin', 'Biochemistry', 680, 610, 1, TRUE, false, '["May reflect excess supplementation, inflammation (for ferritin) or other causes.","May indicate deficiency or depleted stores, depending on the marker.","Tell the clinician about supplements; fasting requirements vary.","Ferritin can rise with inflammation; interpret with other iron studies and clinical history."]'::jsonb) ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, normal_price = EXCLUDED.normal_price, discount_price = EXCLUDED.discount_price, notes = EXCLUDED.notes;
INSERT INTO public.test_catalogue (code, owner_id, name, category, normal_price, discount_price, parameters_count, active, is_panel, notes) VALUES ('LEG-044', NULL, 'Fever Panel Comprehensive', 'Serology / Immunology', 2000, 1800, 5, TRUE, true, '["May be associated with the condition being investigated, but false positives and non-disease causes are possible.","A low/negative result may be normal or may not exclude disease, depending on the assay.","Follow the laboratory''s sample, fasting and timing instructions.","Use the exact assay''s report range and clinician interpretation; this is a general educational note."]'::jsonb) ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, normal_price = EXCLUDED.normal_price, discount_price = EXCLUDED.discount_price, notes = EXCLUDED.notes;
INSERT INTO public.test_catalogue (code, owner_id, name, category, normal_price, discount_price, parameters_count, active, is_panel, notes) VALUES ('LEG-045', NULL, 'Folic Acid', 'Biochemistry', 800, 720, 1, TRUE, false, '["May reflect excess supplementation, inflammation (for ferritin) or other causes.","May indicate deficiency or depleted stores, depending on the marker.","Tell the clinician about supplements; fasting requirements vary.","Ferritin can rise with inflammation; interpret with other iron studies and clinical history."]'::jsonb) ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, normal_price = EXCLUDED.normal_price, discount_price = EXCLUDED.discount_price, notes = EXCLUDED.notes;
INSERT INTO public.test_catalogue (code, owner_id, name, category, normal_price, discount_price, parameters_count, active, is_panel, notes) VALUES ('LEG-046', NULL, 'Free Thyroid Panel (FT3, FT4, TSH)', 'Biochemistry', 900, 810, 3, TRUE, true, '["May suggest overactive thyroid or autoimmune activity depending on the test.","May suggest underactive thyroid for hormone tests; antibody results require context.","Usually blood sample; tell the clinician about thyroid medicines and supplements.","Pregnancy and age affect reference intervals; antibody positivity alone is not a complete diagnosis."]'::jsonb) ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, normal_price = EXCLUDED.normal_price, discount_price = EXCLUDED.discount_price, notes = EXCLUDED.notes;
INSERT INTO public.test_catalogue (code, owner_id, name, category, normal_price, discount_price, parameters_count, active, is_panel, notes) VALUES ('LEG-047', NULL, 'G6PD', 'Haematology', 600, 540, 1, TRUE, false, '["May be associated with the condition being investigated, but false positives and non-disease causes are possible.","A low/negative result may be normal or may not exclude disease, depending on the assay.","Follow the laboratory''s sample, fasting and timing instructions.","Use the exact assay''s report range and clinician interpretation; this is a general educational note."]'::jsonb) ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, normal_price = EXCLUDED.normal_price, discount_price = EXCLUDED.discount_price, notes = EXCLUDED.notes;
INSERT INTO public.test_catalogue (code, owner_id, name, category, normal_price, discount_price, parameters_count, active, is_panel, notes) VALUES ('LEG-048', NULL, 'GTT', 'Biochemistry', 420, 380, 2, TRUE, true, '["May indicate hyperglycaemia, diabetes or impaired glucose regulation; diagnosis requires accepted criteria and sometimes repeat testing.","May indicate hypoglycaemia or treatment-related low glucose.","Fasting may be required for FBS/GTT; HbA1c usually does not require fasting.","Clinical diagnosis should follow current diabetes guidelines; HbA1c can be affected by some anaemias and haemoglobin variants."]'::jsonb) ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, normal_price = EXCLUDED.normal_price, discount_price = EXCLUDED.discount_price, notes = EXCLUDED.notes;
INSERT INTO public.test_catalogue (code, owner_id, name, category, normal_price, discount_price, parameters_count, active, is_panel, notes) VALUES ('LEG-049', NULL, 'Gamma GT', 'Biochemistry', 500, 450, 1, TRUE, false, '["May occur with liver-cell injury, bile-duct problems, alcohol/medicine effects or other conditions.","May reflect reduced protein production or other causes depending on the marker.","Usually blood sample; fasting depends on panel and laboratory.","Enzyme elevation does not by itself establish a specific liver disease."]'::jsonb) ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, normal_price = EXCLUDED.normal_price, discount_price = EXCLUDED.discount_price, notes = EXCLUDED.notes;
INSERT INTO public.test_catalogue (code, owner_id, name, category, normal_price, discount_price, parameters_count, active, is_panel, notes) VALUES ('LEG-050', NULL, 'Globulin', 'Biochemistry', 200, 180, 1, TRUE, false, '["May occur with liver-cell injury, bile-duct problems, alcohol/medicine effects or other conditions.","May reflect reduced protein production or other causes depending on the marker.","Usually blood sample; fasting depends on panel and laboratory.","Enzyme elevation does not by itself establish a specific liver disease."]'::jsonb) ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, normal_price = EXCLUDED.normal_price, discount_price = EXCLUDED.discount_price, notes = EXCLUDED.notes;
INSERT INTO public.test_catalogue (code, owner_id, name, category, normal_price, discount_price, parameters_count, active, is_panel, notes) VALUES ('LEG-051', NULL, 'HBsAg', 'Serology / Immunology', 200, 180, 1, TRUE, false, '["A positive/reactive result may indicate current or past infection depending on the assay.","A negative result may not exclude very early infection or infection outside the test''s detection window.","Sample type and timing are test-specific; follow collection instructions.","Confirmatory testing and clinical correlation may be required; screening tests are not always definitive."]'::jsonb) ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, normal_price = EXCLUDED.normal_price, discount_price = EXCLUDED.discount_price, notes = EXCLUDED.notes;
INSERT INTO public.test_catalogue (code, owner_id, name, category, normal_price, discount_price, parameters_count, active, is_panel, notes) VALUES ('LEG-052', NULL, 'HCV Antibody', 'Serology / Immunology', 500, 450, 1, TRUE, false, '["A positive/reactive result may indicate current or past infection depending on the assay.","A negative result may not exclude very early infection or infection outside the test''s detection window.","Sample type and timing are test-specific; follow collection instructions.","Confirmatory testing and clinical correlation may be required; screening tests are not always definitive."]'::jsonb) ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, normal_price = EXCLUDED.normal_price, discount_price = EXCLUDED.discount_price, notes = EXCLUDED.notes;
INSERT INTO public.test_catalogue (code, owner_id, name, category, normal_price, discount_price, parameters_count, active, is_panel, notes) VALUES ('LEG-053', NULL, 'HDL Cholesterol', 'Biochemistry', 180, 160, 1, TRUE, false, '["Higher LDL/non-HDL/triglycerides may increase cardiovascular risk; interpretation depends on age and overall risk.","Very low values need context; low HDL can be a risk marker.","Fasting may be requested for selected situations; follow the ordering clinician/lab instructions.","See the dedicated Lipid Profile Reference Notes sheet. Values are not a diagnosis or a personal treatment target."]'::jsonb) ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, normal_price = EXCLUDED.normal_price, discount_price = EXCLUDED.discount_price, notes = EXCLUDED.notes;
