INSERT INTO public.test_catalogue (code, owner_id, name, category, normal_price, discount_price, parameters_count, active, is_panel, notes) VALUES ('LEG-111', NULL, 'Urine Routine', 'Clinical Pathology', 80, 70, 8, TRUE, true, '["May indicate infection, blood, protein, glucose or kidney/urinary tract issues.","Often not meaningful in isolation; depends on the measured component.","Clean-catch midstream sample may be requested; culture samples need sterile collection.","Hydration, contamination and collection technique can affect results."]'::jsonb) ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, normal_price = EXCLUDED.normal_price, discount_price = EXCLUDED.discount_price, notes = EXCLUDED.notes;
