INSERT INTO public.test_catalogue (code, owner_id, name, category, normal_price, discount_price, parameters_count, active, is_panel, notes) VALUES ('LEG-113', NULL, 'VLDL', 'Biochemistry', 100, 90, 1, TRUE, false, '["Higher LDL/non-HDL/triglycerides may increase cardiovascular risk; interpretation depends on age and overall risk.","Very low values need context; low HDL can be a risk marker.","Fasting may be requested for selected situations; follow the ordering clinician/lab instructions.","See the dedicated Lipid Profile Reference Notes sheet. Values are not a diagnosis or a personal treatment target."]'::jsonb) ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, normal_price = EXCLUDED.normal_price, discount_price = EXCLUDED.discount_price, notes = EXCLUDED.notes;
